local function decodeEmbeddedBase64(value)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output = {}
    local buffer = 0
    local bits = 0
    for index = 1, #value do
        local character = value:sub(index, index)
        if character == "=" then
            break
        end
        local position = alphabet:find(character, 1, true)
        if position then
            buffer = buffer * 64 + position - 1
            bits += 6
            if bits >= 8 then
                bits -= 8
                output[#output + 1] = string.char(math.floor(buffer / 2 ^ bits) % 256)
                buffer %= 2 ^ bits
            end
        end
    end
    return table.concat(output)
end

-- Local build: icons resolve to Roblox-hosted assets only.
