local function clientUsesMobileLayout(viewport)
    local platformIsMobile = false
    local readPlatform, platform = pcall(function()
        return UserInputService:GetPlatform()
    end)
    if readPlatform then
        platformIsMobile = platform == Enum.Platform.Android
            or platform == Enum.Platform.IOS
    end

    local phoneSized = viewport.X <= 1100 and viewport.Y <= 700
    return platformIsMobile or UserInputService.TouchEnabled or phoneSized
end

