-- GUI names each module owns, so switching modules tears the old one down.
-- Both cheat modules are embedded as base64. Nothing is ever downloaded at runtime.
local EMBEDDED_MODULES = {
    ["pt.lua"] = "",
    ["AutoBoss.lua"] = "",
}
local MODULE_GUIS = {
    ["pt.lua"] = { "BRHub", "Young0xAutoKillHub", "BRStarsMode", "BRAfkGui" },
    ["AutoBoss.lua"] = { "Young0xAutoBossUI" },
}

local function closeModule(file)
    local names = MODULE_GUIS[file]
    if not names then return end
    for _, guiName in ipairs(names) do
        local gui = playerGui:FindFirstChild(guiName)
        if gui then pcall(function() gui:Destroy() end) end
    end
end

local function runModule(file)
    if moduleInMaintenance(file) then
        return false
    end
    -- stop any other running module, then reset this one
    for otherFile in pairs(MODULE_GUIS) do
        if otherFile ~= file then
            closeModule(otherFile)
        end
    end
    closeModule(file)
    local encoded = EMBEDDED_MODULES[file]
    local ok, err = pcall(function()
        if type(encoded) ~= "string" or #encoded == 0 then
            error("module not embedded: " .. tostring(file))
        end
        local source = decodeEmbeddedBase64(encoded)
        loadstring(source, "@" .. file)()
    end)
    if not ok then
        warn("[Local Hub] " .. file .. ": " .. tostring(err))
    end
    return ok
end

