        statusLabel.Text = text
        statusLabel.TextColor3 = color or COLOR.Text
        playTween(statusLabel, 0.16, { TextTransparency = 0 }, Enum.EasingStyle.Quart)
        task.delay(duration or 2.4, function()
            if serial ~= statusSerial or not statusLabel.Parent then
                return
            end
            local fade = playTween(statusLabel, 0.22, { TextTransparency = 1 }, Enum.EasingStyle.Quart)
            track(fade.Completed:Connect(function()
                if serial == statusSerial and statusLabel.Parent then
                    statusLabel.Text = ""
                    statusLabel.TextTransparency = 1
                end
            end))
            task.delay(0.25, function()
                if serial == statusSerial and statusLabel.Parent then
                    statusLabel.Text = ""
                    statusLabel.TextTransparency = 1
                end
            end)
        end)
    end

    local function showShopStatus(text)
        shopStatusSerial += 1
        local serial = shopStatusSerial
        shopStatus.Text = text
        playTween(shopStatus, 0.16, { TextTransparency = 0 }, Enum.EasingStyle.Quart)
        task.delay(2, function()
            if serial ~= shopStatusSerial or not shopStatus.Parent then
                return
            end
            playTween(shopStatus, 0.2, { TextTransparency = 1 }, Enum.EasingStyle.Quart)
            task.delay(0.22, function()
                if serial == shopStatusSerial and shopStatus.Parent then
                    shopStatus.Text = ""
                    shopStatus.TextTransparency = 1
                end
            end)
        end)
    end

    local function copyDiscord(fromShop)
        local clipboard = rawget(Environment, "setclipboard")
            or rawget(Environment, "toclipboard")
            or rawget(_G, "setclipboard")
            or rawget(_G, "toclipboard")
        if type(clipboard) == "function" then
            pcall(clipboard, DISCORD_URL)
        end
        if fromShop then
            showShopStatus("Link copied")
        else
            showLoaderStatus("Link copied", COLOR.Green, 2)
        end
    end

    local function copyYouTube()
        local clipboard = rawget(Environment, "setclipboard")
            or rawget(Environment, "toclipboard")
            or rawget(_G, "setclipboard")
            or rawget(_G, "toclipboard")
        if type(clipboard) == "function" then
            pcall(clipboard, YOUTUBE_URL)
        end
        showLoaderStatus("Link copied", COLOR.Green, 2)
    end

    local function animateButton(button, buttonScale, callback, hoverScale)
        track(button.MouseEnter:Connect(function()
            if not closing then
                playTween(buttonScale, 0.22, { Scale = hoverScale or 1.15 }, Enum.EasingStyle.Back)
            end
        end))
        track(button.MouseLeave:Connect(function()
            playTween(buttonScale, 0.2, { Scale = 1 }, Enum.EasingStyle.Quint)
        end))
        track(button.Activated:Connect(function()
            if closing or transitioning then
                return
            end
            playTween(buttonScale, 0.07, { Scale = 0.88 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
            task.delay(0.07, function()
                if buttonScale.Parent then
                    playTween(buttonScale, 0.2, { Scale = hoverScale or 1.15 }, Enum.EasingStyle.Back)
                end
            end)
            callback()
        end))
    end

    local function setModuleHover(state, hovering)
        state.hovered = hovering
        if state.module.maintenance then
            return
        end
        playTween(state.button, 0.26, {
            BackgroundTransparency = hovering and 0.91 or 1,
        }, Enum.EasingStyle.Quint)
        playTween(state.visualScale, 0.32, {
            Scale = hovering and 1.095 or 1,
        }, hovering and Enum.EasingStyle.Back or Enum.EasingStyle.Quint)
        playTween(state.icon, 0.26, {
            ImageTransparency = hovering and 0 or 0.03,
        }, Enum.EasingStyle.Quint)
        playTween(state.name, 0.28, {
            TextColor3 = hovering and COLOR.White or COLOR.Text,
        }, Enum.EasingStyle.Quint)
        playTween(state.dot, 0.28, {
            Size = hovering and UDim2.fromOffset(13, 13) or UDim2.fromOffset(10, 10),
        }, Enum.EasingStyle.Back)
    end

    local function pulseModule(state)
        state.clickSerial += 1
        local serial = state.clickSerial
        playTween(state.visualScale, 0.08, { Scale = 0.94 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        task.delay(0.08, function()
            if serial == state.clickSerial and state.visualScale.Parent then
                playTween(state.visualScale, 0.24, {
                    Scale = state.hovered and 1.095 or 1,
                }, Enum.EasingStyle.Back)
            end
        end)
    end

    for index, module in ipairs(MODULES) do
        local maintenance = module.maintenance == true

        local button = create("TextButton", {
            Name = "Module_" .. index,
            Size = UDim2.new(1 / moduleCount, 0, 1, 0),
            Position = UDim2.new((index - 1) / moduleCount, 0, 0, 0),
            BackgroundColor3 = COLOR.Hover,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 15,
        }, moduleArea)

        local visual = create("Frame", {
            Name = "Visual",
            AnchorPoint = Vector2.new(0.5, 0),
            Size = UDim2.fromOffset(moduleVisualWidth, 224),
            Position = UDim2.new(0.5, 0, 0, 2),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 18,
        }, button)
        local visualScale = create("UIScale", { Scale = 1 }, visual)

        local icon = create("ImageLabel", {
            Name = "Icon",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.fromOffset(module.iconSize or 84, module.iconSize or 84),
            Position = UDim2.new(0.5, 0, 0, module.iconY or 57),
            BackgroundTransparency = 1,
            Image = module.icon,
            ImageColor3 = maintenance and COLOR.Disabled or COLOR.White,
            ImageTransparency = maintenance and 0.26 or 0.03,
            ScaleType = Enum.ScaleType.Fit,
            ZIndex = 19,
        }, visual)

        local nameLabel = create("TextLabel", {
            Name = "Name",
            Size = UDim2.new(1, 0, 0, 42),
            Position = UDim2.fromOffset(0, 158),
            BackgroundTransparency = 1,
            Text = module.name,
            Font = Enum.Font.GothamBold,
            TextSize = moduleNameSize,
            TextColor3 = maintenance and COLOR.Disabled or COLOR.Text,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 19,
        }, visual)

        local dot = create("Frame", {
            Name = "StatusDot",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.fromOffset(12, 12),
            Position = UDim2.new(0.5, 0, 0, 214),
            BackgroundColor3 = maintenance and COLOR.Disabled or module.accent,
            BorderSizePixel = 0,
            ZIndex = 19,
        }, visual)
        corner(dot, 99)

        local state = {
            module = module,
            button = button,
            visual = visual,
            visualScale = visualScale,
            icon = icon,
            name = nameLabel,
            dot = dot,
            hovered = false,
            clickSerial = 0,
            offsetX = 0,
            offsetY = 0,
        }
        moduleStates[index] = state

        track(button.MouseEnter:Connect(function()
            if not closing then
                setModuleHover(state, true)
            end
        end))

        track(button.MouseLeave:Connect(function()
            setModuleHover(state, false)
        end))

        track(button.Activated:Connect(function()
            if closing or launching or transitioning then
                return
            end
            pulseModule(state)
            if maintenance then
                showLoaderStatus("Update in progress", COLOR.Subtext, 2.2)
                return
            end

            launching = true
            task.delay(0.12, function()
                if gui.Parent then
                    closeAndRun(module.file)
                end
            end)
        end))
    end

    local function exitAnimation(onComplete)
        if closing then
            return
        end
        closing = true
        dragging = false
        local exitTween = playTween(stage, 0.2, {
            GroupTransparency = 1,
            Position = UDim2.new(stage.Position.X.Scale, stage.Position.X.Offset, stage.Position.Y.Scale, stage.Position.Y.Offset + 18),
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        playTween(scale, 0.2, { Scale = scale.Scale * 0.93 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        track(exitTween.Completed:Connect(function()
            destroyLoader()
            if onComplete then
                onComplete()
            end
        end))
    end

    closeOnly = function()
        if launching then
            return
        end
        exitAnimation()
    end

    closeAndRun = function(file)
        exitAnimation(function()
            runModule(file)
        end)
    end

    local function showShop()
        if closing or transitioning or launching then
            return
        end
        transitioning = true
        statusSerial += 1
        shopStatus.Text = ""
        shopStatus.TextTransparency = 1
        playTween(loaderPage, 0.16, { GroupTransparency = 1 }, Enum.EasingStyle.Quart)
        playTween(stage, 0.38, { Size = UDim2.fromOffset(SHOP_WIDTH, SHOP_HEIGHT) }, Enum.EasingStyle.Quint)
        task.delay(0.16, function()
            if not stage.Parent then return end
            loaderPage.Visible = false
            shopPage.Visible = true
            shopPage.GroupTransparency = 1
            playTween(shopPage, 0.24, { GroupTransparency = 0 }, Enum.EasingStyle.Quint)
            currentWidth = SHOP_WIDTH
            currentHeight = SHOP_HEIGHT
            if updateScale then
                updateScale(true)
            end
            task.delay(0.24, function()
                transitioning = false
            end)
        end)
    end

    local function showLoader()
        if closing or transitioning then
            return
        end
        transitioning = true
        shopStatusSerial += 1
        shopStatus.Text = ""
        shopStatus.TextTransparency = 1
        playTween(shopPage, 0.16, { GroupTransparency = 1 }, Enum.EasingStyle.Quart)
        playTween(stage, 0.38, { Size = UDim2.fromOffset(WIDTH, HEIGHT) }, Enum.EasingStyle.Quint)
        task.delay(0.16, function()
            if not stage.Parent then return end
            shopPage.Visible = false
            loaderPage.Visible = true
            loaderPage.GroupTransparency = 1
            playTween(loaderPage, 0.24, { GroupTransparency = 0 }, Enum.EasingStyle.Quint)
            currentWidth = WIDTH
            currentHeight = HEIGHT
            if updateScale then
                updateScale(true)
            end
            task.delay(0.24, function()
                transitioning = false
            end)
        end)
    end

    animateButton(discordButton, discordScale, function()
        copyDiscord(false)
    end, 1.16)
    animateButton(shopButton, shopScale, showShop, 1.16)
    animateButton(youtubeButton, youtubeScale, copyYouTube, 1.16)
    track(shopDiscord.Activated:Connect(function()
        copyDiscord(true)
    end))
    animateButton(backButton, backScale, showLoader, 1.035)
    track(backButton.MouseEnter:Connect(function()
        if not closing then
            playTween(backButton, 0.2, {
                BackgroundTransparency = 1,
                TextColor3 = COLOR.White,
            }, Enum.EasingStyle.Quint)
            playTween(backStroke, 0.2, { Transparency = 1 }, Enum.EasingStyle.Quint)
        end
    end))
    track(backButton.MouseLeave:Connect(function()
        playTween(backButton, 0.2, {
            BackgroundTransparency = 1,
            TextColor3 = COLOR.White,
        }, Enum.EasingStyle.Quint)
        playTween(backStroke, 0.2, { Transparency = 1 }, Enum.EasingStyle.Quint)
    end))

    local function bindClose(button, buttonScale)
        track(button.MouseEnter:Connect(function()
            if not closing then
                playTween(buttonScale, 0.2, { Scale = 1.12 }, Enum.EasingStyle.Back)
            end
        end))
        track(button.MouseLeave:Connect(function()
            playTween(buttonScale, 0.18, { Scale = 1 }, Enum.EasingStyle.Quint)
        end))
        track(button.Activated:Connect(closeOnly))
    end
    bindClose(closeButton, closeScale)

    local function bindDrag(dragHeader)
        track(dragHeader.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragInput = input
                dragStart = input.Position
                dragOrigin = dragTarget
                track(input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                    end
                end))
            end
        end))
    end
    bindDrag(header)
    bindDrag(titleButton)
    bindDrag(shopHeader)
    bindDrag(shopTitle)

    track(UserInputService.InputChanged:Connect(function(input)
        if dragging and not closing
            and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            dragTarget = UDim2.new(
                dragOrigin.X.Scale,
                dragOrigin.X.Offset + delta.X,
                dragOrigin.Y.Scale,
                dragOrigin.Y.Offset + delta.Y
            )
        end
    end))

    track(RunService.RenderStepped:Connect(function(deltaTime)
        if not closing then
            local dragAlpha = 1 - math.exp(-10 * math.min(deltaTime, 0.05))
            stage.Position = stage.Position:Lerp(dragTarget, dragAlpha)
        end

        local pointer = UserInputService:GetMouseLocation()
        for _, state in ipairs(moduleStates) do
            local targetX = 0
            local targetY = 0
            if state.hovered and not state.module.maintenance and loaderPage.Visible then
                local absolutePosition = state.button.AbsolutePosition
                local absoluteSize = state.button.AbsoluteSize
                if absoluteSize.X > 0 and absoluteSize.Y > 0 then
                    local relativeX = math.clamp((pointer.X - absolutePosition.X) / absoluteSize.X - 0.5, -0.5, 0.5)
                    local relativeY = math.clamp((pointer.Y - absolutePosition.Y) / absoluteSize.Y - 0.5, -0.5, 0.5)
                    targetX = relativeX * 14
                    targetY = relativeY * 10
                end
            end
            local motionAlpha = 1 - math.exp(-13 * math.min(deltaTime, 0.05))
            state.offsetX += (targetX - state.offsetX) * motionAlpha
            state.offsetY += (targetY - state.offsetY) * motionAlpha
            state.visual.Position = UDim2.new(0.5, state.offsetX, 0, 2 + state.offsetY)
        end
    end))

    updateScale = function(animated)
        camera = workspace.CurrentCamera or camera
        if not camera then
            return
        end
        local viewport = camera.ViewportSize
        local mobile = clientUsesMobileLayout(viewport)
        for _, state in ipairs(moduleStates) do
            local iconSize = mobile
                and (state.module.mobileIconSize or state.module.iconSize or 84)
                or (state.module.iconSize or 84)
            local iconY = mobile
                and (state.module.mobileIconY or state.module.iconY or 57)
                or (state.module.iconY or 57)
            state.icon.Size = UDim2.fromOffset(iconSize, iconSize)
            state.icon.Position = UDim2.new(0.5, 0, 0, iconY)
        end
        local compactDesktop = not mobile
            and (viewport.X <= 1100 or viewport.Y <= 650)
        local horizontalPadding
        local verticalPadding
        local maximumScale
        local minimumScale

        if mobile then
            horizontalPadding = math.max(52, viewport.X * 0.18)
            verticalPadding = math.max(92, viewport.Y * 0.32)
            maximumScale = MOBILE_MAX_SCALE
            minimumScale = 0.22
        elseif compactDesktop then
            horizontalPadding = 28
            verticalPadding = 40
            maximumScale = COMPACT_DESKTOP_MAX_SCALE
            minimumScale = 0.30
        else
            horizontalPadding = 34
            verticalPadding = 46
            maximumScale = DESKTOP_MAX_SCALE
            minimumScale = 0.30
        end

        local availableWidth = math.max(viewport.X - horizontalPadding, 1)
        local availableHeight = math.max(viewport.Y - verticalPadding, 1)
        local fittedScale = math.min(
            availableWidth / currentWidth,
            availableHeight / currentHeight,
            maximumScale
        )
        local targetScale = math.max(fittedScale, minimumScale)
        if animated then
            playTween(scale, 0.3, { Scale = targetScale }, Enum.EasingStyle.Quint)
        else
            scale.Scale = targetScale
        end
    end

    local function applyTypography(object)
        if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            object.Font = Enum.Font.Gotham
        end
    end
    for _, object in ipairs(gui:GetDescendants()) do
        applyTypography(object)
    end
    track(gui.DescendantAdded:Connect(applyTypography))

    updateScale()
    if camera then
        track(camera:GetPropertyChangedSignal("ViewportSize"):Connect(updateScale))
    end
    track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        camera = workspace.CurrentCamera
        updateScale()
    end))

    local finalScale = scale.Scale
    scale.Scale = finalScale * 0.93
    playTween(stage, 0.3, { GroupTransparency = 0 }, Enum.EasingStyle.Quint)
    playTween(scale, 0.36, { Scale = finalScale }, Enum.EasingStyle.Back)

    
    return
end
